def to_yaml(questions):
    return "\n".join(
        f"- q: {json.dumps(q)}\n  options: {json.dumps(opts)}\n  answer: {ans}" + (f"\n  explain: {json.dumps(ex)}" if ex else "")
        for q, opts, ans, ex in questions
    )


if __name__ == "__main__":
    root = os.path.join(os.path.dirname(__file__), "..", "content", "tracks")
    for track, questions in BANKS.items():
        path = os.path.join(root, f"{track}.md")
        text = open(path).read()
        text = re.sub(r"\n```exam\n.*?\n```\n?$", "\n", text, flags=re.S).rstrip() + "\n"
        text += f"\n```exam\n{to_yaml(questions)}\n```\n"
        open(path, "w").write(text)
        print(f"{track}: {len(questions)} exam questions")
